import numpy as np
from scipy.spatial.transform import Rotation
class Kin:
 def __init__(self,s):
  self.s=s;self.names=s['links']['names'];self.parents=s['links']['parent'];self.com=np.array(s['links']['com_m']);self.mass=np.array(s['links']['mass_kg']);self.jnames=s['proprio']['joints'];self.axes=np.array(s['proprio']['axis']);self.pos=np.array(s['proprio']['position_m']);self.map={}
  for i,n in enumerate(self.jnames):
   if n.startswith(('lh_','rh_')):
    pre=n[:3];suf=n[3:];d={'WRJ2':'wrist','WRJ1':'palm'}
    for f in ['FF','MF','RF','LF']:
     for j,link in [(4,'knuckle'),(3,'proximal'),(2,'middle'),(1,'distal')]:d[f+'J'+str(j)]=f.lower()+link
    d['LFJ5']='lfmetacarpal'
    for j,link in [(5,'base'),(4,'proximal'),(3,'hub'),(2,'middle'),(1,'distal')]:d['THJ'+str(j)]='th'+link
    child=pre+d[suf]
   elif n.endswith('wrist_yaw'):child=n.split('_')[0]+'_hand'
   else:child=n+'_link'
   self.map[child]=i
 def forward(self,q):
  ts={'pelvis':np.eye(4)}
  for n,p in zip(self.names[1:],self.parents[1:]):
   i=self.map[n];rot=Rotation.from_rotvec(self.axes[i]*q[i]).as_matrix();t=np.eye(4);t[:3,:3]=rot;t[:3,3]=self.pos[i]-rot@self.pos[i];ts[n]=ts[p]@t
  return ts
 def measure(self,o):
  ts=self.forward(o['proprio']['joint_pos']);g=np.array(o['imu']['gravity']);R=Rotation.align_vectors([[0,0,1]],[-g])[0].as_matrix()
  coms=np.array([(ts[n]@np.r_[p,1])[:3] for n,p in zip(self.names,self.com)]);com=R@(self.mass@coms/self.mass.sum())
  feet=[]
  for n,box in self.s['links']['feet'].items():
   point=np.mean(box,axis=0);point[2]=box[0][2];feet.append(R@(ts[n]@np.r_[point,1])[:3])
  center=np.mean(feet,axis=0)
  return com-center,ts,R
