from PIL import Image
from scipy.spatial import ConvexHull
COLORS={'O':(.42,.55),'P':(.12,.20),'E':(.62,.74),'N':(.75,.86),'A':(.86,.98),'I':(-.03,.05)}
def hsv(im):
 a=np.array(im)/255.;mx=a.max(2);mn=a.min(2);d=mx-mn;h=np.zeros(mx.shape);sat=d/np.maximum(mx,1e-8)
 for idx in range(3):
  v=(a[:,:,(idx+1)%3]-a[:,:,(idx+2)%3])/np.maximum(d,1e-8)+idx*2
  h=np.where(a[:,:,idx]==mx,v,h)
 return (h/6)%1,sat,mx
def getfaces(path,roi):
 im=np.array(Image.open(path));h,s,v=hsv(im);x0,y0,x1,y1=roi;faces={}
 for c,(lo,hi) in COLORS.items():
  mask=(h>lo)&(h<hi)&(s>.13)&(v>.15)
  if c=='I':mask=((h<hi)|(h>1+lo))&(s>.13)&(v>.15)
  y,x=np.where(mask[y0:y1,x0:x1]);pts=np.array([x+x0,y+y0]).T
  if len(pts)<5:continue
  hull=pts[ConvexHull(pts).vertices]
  # Iteratively remove shallow corners to leave polygon with four vertices
  poly=list(hull.astype(float))
  while len(poly)>4:
   areas=[abs(np.cross(poly[i]-poly[i-1],poly[(i+1)%len(poly)]-poly[i])) for i in range(len(poly))]
   poly.pop(int(np.argmin(areas)))
  faces[c]=np.array(poly)
 return faces
